        enrolled = self.client.post('/enrollments', json={'child_id': child['id'], 'classroom_id': classroom['id']}).get_json()
        immunization = self.client.post('/immunizations', json={'child_id': child['id'], 'vaccine': 'MMR'}).get_json()
